                              import java.util.List;
                              import java.util.Scanner;

                              public class MainApp {
                                  private static final Scanner scanner = new Scanner(System.in);
                                  private static final UserManager userManager = new UserManager();

                                  public static void main(String[] args) {
                                      while (true) {
                                          printMenu();

                                          if (!scanner.hasNextInt()) {
                                              System.out.println("❌ Ошибка: Введите число от 0 до 6!");
                                              scanner.nextLine();
                                              continue;
                                          }

                                          int choice = scanner.nextInt();
                                          scanner.nextLine(); // Очистка буфера

                                          if (choice == 0) {
                                              System.out.println("Программа завершена. До свидания!");
                                              break;
                                          }

                                          // Весь огромный switch теперь выглядит как простая и понятная таблица сигналов
                                          switch (choice) {
                                              case 1, 2, 3 -> handleFillStrategy(choice);
                                              case 4       -> handleDisplayUsers();
                                              case 5       -> handleExportToFile();
                                              case 6       -> handleSorting();
                                              default      -> System.out.println("❌ Неверный выбор. Пожалуйста, выберите пункт от 0 до 6.");
                                          }
                                      }
                                      scanner.close();
                                  }

                                  // --- МЕТОДЫ ВЫВОДА МЕНЮ И ОБРАБОТКИ КОМАНД ---

                                  private static void printMenu() {
                                      System.out.println("\n================= ГЛАВНОЕ МЕНЮ =================");
                                      System.out.println("1. Заполнить массив случайными пользователями");
                                      System.out.println("2. Заполнить массив вручную (через консоль)");
                                      System.out.println("3. Заполнить массив из файла");
                                      System.out.println("4. Вывести полученный массив на экран 📺");
                                      System.out.println("5. Сохранить текущий массив в файл 💾");
                                      System.out.println("6. Отсортировать массив по полям 🔀");
                                      System.out.println("0. Выйти из программы");
                                      System.out.print("Выберите действие: ");
                                  }

                                  // Обработка пунктов 1, 2, 3 (Заполнение массива)
                                  private static void handleFillStrategy(int choice) {
                                      System.out.print("Введите желаемую длину массива (количество пользователей): ");
                                      while (!scanner.hasNextInt()) {
                                          System.out.println("❌ Ошибка: Длина должна быть целым числом!");
                                          System.out.print("Повторите ввод: ");
                                          scanner.nextLine();
                                      }
                                      int count = scanner.nextInt();
                                      scanner.nextLine(); // Очистка буфера

                                      if (count <= 0) {
                                          System.out.println("⚠ Длина массива должна быть больше 0. Возврат в меню.");
                                          return;
                                      }

                                      userManager.clear(); 

                                      switch (choice) {
                                          case 1 -> userManager.setStrategy(new RandomFillStrategy(count));
                                          case 2 -> userManager.setStrategy(new ConsoleFillStrategy(count));
                                          case 3 -> {
                                              System.out.print("Введите путь к файлу для чтения (например, input.txt): ");
                                              String filePath = scanner.nextLine();
                                              userManager.setStrategy(new FileFillStrategy(filePath, count));
                                          }
                                      }
                                      userManager.populateUsers();
                                  }

                                  // Обработка пункта 4 (Вывод на экран)
                                  private static void handleDisplayUsers() {
                                      System.out.println("\n--- 📜 ТЕКУЩИЙ МАССИВ ПОЛЬЗОВАТЕЛЕЙ ---");
                                      List<User> currentUsers = userManager.getUsers();

                                      if (currentUsers.isEmpty()) {
                                          System.out.println("❌ Массив пуст. Сначала заполните его (пункты 1-3).");
                                          return;
                                      }

                                      System.out.println("Всего элементов в массиве: " + currentUsers.size());
                                      for (int i = 0; i < currentUsers.size(); i++) {
                                          System.out.println("[" + (i + 1) + "] " + currentUsers.get(i));
                                      }
                                      System.out.println("----------------------------------------");
                                  }

                                  // Обработка пункта 5 (Сохранение в файл)
                                  private static void handleExportToFile() {
                                      if (userManager.getUsers().isEmpty()) {
                                          System.out.println("❌ Нечего сохранять. Сначала заполните массив (пункты 1-3).");
                                          return;
                                      }
                                      System.out.print("Введите путь для сохранения файла (например, output.txt): ");
                                      String filePath = scanner.nextLine();

                                      userManager.setExportStrategy(new FileExportStrategy(filePath));
                                      userManager.exportUsers();
                                  }

                                  // Обработка пункта 6 (Сортировка)
                                  private static void handleSorting() {
                                      if (userManager.getUsers().isEmpty()) {
                                          System.out.println("❌ Массив пуст. Нечего сортировать.");
                                          return;
                                      }

                                      System.out.println("\n--- Выберите поле для сортировки ---");
                                      System.out.println("1. По полю 1 (Имя)");
                                      System.out.println("2. По полю 2 (Пароль)");
                                      System.out.println("3. По полю 3 (Email)");
                                      System.out.print("Ваш выбор: ");

                                      if (!scanner.hasNextInt()) {
                                          System.out.println("❌ Неверный ввод. Возврат в главное меню.");
                                          scanner.nextLine();
                                          return;
                                      }

                                      int fieldChoice = scanner.nextInt();
                                      scanner.nextLine(); // Очистка буфера

                                      switch (fieldChoice) {
                                          case 1 -> userManager.sortUsers(User.BY_NAME);
                                          case 2 -> userManager.sortUsers(User.BY_PASSWORD);
                                          case 3 -> userManager.sortUsers(User.BY_EMAIL);
                                          default -> System.out.println("❌ Неверный вариант поля. Сортировка отменена.");
                                      }
                                  }
                              }
